export type TFrameType = (
	'for-next' |
	'for-from' |
	'null' |
	'external' |
	'eval' |
	'native' |
	'constructor' |
	'method' |
	'function' |
	'script' |
	'unknown'
	)

const getFrameType = (
		site: CallSite,
		name: string
		): TFrameType => {

	const source = site.getFileName()
	if (notdefined(source)) {
		return (
			  (name === 'next') ? 'for-next'
			: (name === 'from') ? 'for-from'
			:                    'null'
			)
	}
	return (
		  source.startsWith('ext:') ? 'external'
		: site.getFunctionName()    ? 'function'
		: site.getMethodName()      ? 'method'
		: site.isTopLevel           ? 'script'
		: site.isEval()             ? 'eval'
		: site.isNative()           ? 'native'
		: site.isConstructor()      ? 'constructor'
		:                             'script'
		)
}

