export const allStackFrames = function*(): TIterator<TStackFrame> {

	openDebugFile('stack')

	try {
		// @ts-ignore
		const oldLimit = Error.stackTraceLimit
		// @ts-ignore
		const oldPreparer = Error.prepareStackTrace
		// @ts-ignore
		Error.stackTraceLimit = 99

		let prevFrame: (TStackFrame | undefined) = undefined

		// @ts-ignore
		Error.prepareStackTrace = (
				error,
				lOrgFrames: CallSite[]
				) => {

			if (lOrgFrames.length === 0) {
				console.log("===== lOrgFrames is EMPTY =====")
			}
			let lFrames: TStackFrame[] = []    // return value
			let i1 = 0;for (const orgFrame of lOrgFrames) {const i = i1++;

				let source: string = orgFrame.getFileName() || ''
				if (source) {
					source = toRelPath(source)
				}
				let line: number = orgFrame.getLineNumber() || -1
				let col: number  = orgFrame.getColumnNumber() || -1
				const name: string = (
					   orgFrame.getFunctionName()
					|| orgFrame.getMethodName()
					|| ''
					)
				const type: TFrameType = getFrameType(orgFrame, name)

				// --- Get an initial frame object
				const frame: TStackFrame = {
					i,
					type,
					orgSource: source,
					orgLine:   line,
					orgCol:    col,
					source:    source,
					line:      line,
					col:       col,
					name
					}

				if (['for-next','for-from','null','external'].includes(type)) {
					lFrames.push(frame)
					continue
				}

				// --- follow source maps recursively
				let newFilePos = mapPosSync({source, line, col})
				while (newFilePos !== undefined) {
					source = newFilePos.source
					if (source) {
						source = toRelPath(source)
					}
					line   = newFilePos.line
					col    = newFilePos.col
					newFilePos = mapPosSync(newFilePos)
				}

				// --- Add new line & col if mapped
				if (source !== frame.orgSource) {
					frame.source = source
					frame.line = line
					frame.col = col
				}

				// --- fix a bug in the V8 engine where calls inside a
				//     top level anonymous function is reported as
				//     being of type 'script'

				if (prevFrame && (frame.type === 'script') && (prevFrame.type === 'script')) {
					prevFrame.type = 'function'
					prevFrame.name = '<anon>'
				}

				prevFrame = frame
				lFrames.push(frame)
			}

			return lFrames
		}

		const obj: Object = {}
		Error.captureStackTrace(obj)
		// @ts-ignore
		const lStack: TStackFrame[] = obj.stack

		if (lStack.length === 0) {
			console.log("===== captureStackTrace returned EMPTY STACK =====")
		}

		// --- reset to previous values
		// @ts-ignore
		Error.stackTraceLimit = oldLimit
		// @ts-ignore
		Error.prepareStackTrace = oldPreparer
		for (const frame of lStack) {
			yield frame
		}
		return
	}

	catch (err) {
		ERR(`${red('ERROR in allStackFrames:')} ${getErrStr(err)}`)
		return
	}
	finally {
		closeDebugFile('stack')
	}
}

