export const frameHdr = (): string => {

	return sprintf("%2s %-8s %-16s %s", 'i', 'type', 'name', 'source')
}

// ---------------------------------------------------------------------------

export const frameStr = (
		frame: TStackFrame,
		): string => {

	const posStr = (line: number, col: number): string => {
		return inUnitTest() ? `${line}:${col}` : green(`${line}:${col}`)
	}

	const {i, type, orgSource, orgLine, orgCol, source, line, col, name} = frame
	const typeStr = sprintf('%-8s', type)
	const nameStr = sprintf('%-16s', name)
	const prefix = `${sprintf('%2d', i)}: ${typeStr} ${nameStr}`
	if (orgSource) {
		const mapped = (source === orgSource) ? '' : ` => ${source} ${posStr(line, col)}`
		return `${prefix} ${orgSource} ${posStr(orgLine, orgCol)}` + mapped
	}
	else {
		return `${prefix} <none>`
	}
}

